package net.civeira.phylax.features.access.user.application.usecase.create;

import net.civeira.phylax.common.security.AuthorizationDecision;
import net.civeira.phylax.common.security.OperationContext;
import net.civeira.phylax.common.security.Permission;

/**
 * Create Allow Decision event is used when a create usecase is invoked, and allow the programer to
 * check claims of the user before accept the operation.
 */
public class UserCreateAuthorizationDecision extends AuthorizationDecision {

  /**
   * @autogenerated CreateAuthorizationDecisionGenerator
   * @param context
   * @param initial
   */
  public UserCreateAuthorizationDecision(final OperationContext context, final Permission initial) {
    super(context, initial);
  }

  /**
   * @autogenerated CreateAuthorizationDecisionGenerator
   * @return
   */
  public String actionName() {
    return "create";
  }

  /**
   * @autogenerated CreateAuthorizationDecisionGenerator
   * @return
   */
  public String resourceName() {
    return "user";
  }
}
